import json, pathlib, sys
sys.path.insert(0, "scripts")
import watchlist

wl = json.loads(pathlib.Path("data/watchlist.json").read_text())["repos"]
p = pathlib.Path("data/watch_series.json")
ser = json.loads(p.read_text())["repos"] if p.exists() else {}
need = set(watchlist.FIELDS) - {"date"}
today = watchlist._today()
bad = []
for name, points in ser.items():
    dates = [pt.get("date") for pt in points]
    if len(set(dates)) != len(dates) or dates != sorted(dates):
        bad.append(name + ":dates")
    for pt in points:
        if pt["date"] > today:
            bad.append(name + ":future")
        miss = need - {k for k, v in pt.items() if v is not None}
        if miss:
            bad.append(name + ":" + ",".join(sorted(miss)))
print("watched", len(wl), "records", len(ser), "problems", bad[:3])
assert wl, "watch list is empty"
assert not bad
PY
